/**
 * Normalizes any product so it always has valid high-res Supabase Storage URLs
 */
export function resolveProductImage<T extends { id?: string; slug?: string; image_url?: string | null; images?: string[] }>(product: T): T {
  if (!product) return product;

  // If already a valid remote Supabase CDN url, return as-is
  if (product.image_url && product.image_url.startsWith('http') && product.image_url.includes('supabase.co')) {
    return product;
  }

  const match = (product.slug && PRODUCT_IMAGE_MAP[product.slug]) ||
                (product.id && PRODUCT_IMAGE_MAP[product.id]) ||
                (product.image_url && OLD_IMAGE_PATH_MAP[product.image_url] ? { image_url: OLD_IMAGE_PATH_MAP[product.image_url], images: [OLD_IMAGE_PATH_MAP[product.image_url]] } : null);

  if (match) {
    return {
      ...product,
      image_url: match.image_url,
      images: (product.images && product.images.length > 0 && product.images[0].startsWith('http'))
        ? product.images
        : match.images,
    };
  }

  return product;
}
